const InterviewCore=(()=>{
 const fields=['goal','role','constraints','age','education','skills','hours','resources','experience','interests','recentUpdate'];
 const labels={goal:'近期想改变的事',role:'目前的职业或身份',constraints:'现实障碍与边界',age:'年龄',education:'最高学历',skills:'擅长的技能',hours:'每周可用时间',resources:'已有资源',experience:'重要经历',interests:'兴趣与偏好',recentUpdate:'最近的变化'};
 const required=['goal','role','constraints','age','education','skills','hours'];
 const known=v=>v!==undefined&&v!==null&&String(v).trim()!==''&&!['未知','不确定','不知道','跳过'].includes(String(v).trim());
 const isNoiseTranscript=value=>/^(?:字幕(?:by|由)[\p{L}\p{N}_-]{1,80}|(?:请不吝|請不吝)?(?:点赞|點贊)(?:订阅|訂閱)(?:转发|轉發)(?:打赏|打賞)支持.{0,40}|(?:感谢观看|感謝觀看|谢谢观看|謝謝觀看|thankyouforwatching){1,4})$/iu.test(String(value||'').replace(/[\s，,。.!！?？:：;；]/g,''));
 const clean=p=>Object.fromEntries(fields.filter(k=>known(p?.[k])).map(k=>[k,k==='hours'?Number(p[k]):String(p[k]).trim().slice(0,2000)]).filter(([k,v])=>k!=='hours'||Number.isFinite(v)&&v>=.5&&v<=80));
 function number(s){if(/^\d+(\.\d+)?$/.test(s))return Number(s);const map={零:0,一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9};if(s==='半')return .5;let n=0,t=0;for(const c of s){if(c==='十'){n+=(t||1)*10;t=0}else if(c==='百'){n+=(t||1)*100;t=0}else if(c in map)t=map[c];else return NaN}return n+t}
 function age(s){const m=s.match(/([0-9零一二两三四五六七八九十百]{1,5})\s*岁/)||s.match(/^\s*([0-9零一二两三四五六七八九十百]{1,5})\s*$/);const n=m?number(m[1]):NaN;return n>=1&&n<=120?String(n):null}
 function hours(s,direct=false){const m=s.match(/([0-9零一二两三四五六七八九十半.]{1,6})\s*(?:个)?小时/)||(direct?s.match(/^\s*([0-9零一二两三四五六七八九十半.]{1,6})\s*$/):null);const n=m?number(m[1]):NaN;return n>=.5&&n<=80?n:null}
 function education(s){for(const [test,value] of [[/博士/,'博士'],[/硕士|研究生/,'硕士'],[/本科|学士/,'本科'],[/大专|专科/,'大专'],[/高中|中专|职高/,'高中 / 中专'],[/初中|小学/,'初中及以下']])if(test.test(s))return value;return null}
 function apply(profile,field,answer,modelFacts=[]){
  const next=clean(profile),evidence={};answer=String(answer||'').trim().slice(0,2000);
  const set=(key,value,quote)=>{if(!known(value))return;next[key]=value;evidence[key]={value,evidence:quote,source:'user'}};
  if(fields.includes(field)&&!['age','hours','education'].includes(field)&&known(answer))set(field,answer,answer);
  const a=(field==='age'||/(?:我|本人)(?:今年|现在|已经)?(?:是)?\s*[0-9零一二两三四五六七八九十百]+岁/.test(answer))?age(answer):null,h=hours(answer,field==='hours'),e=(field==='education'||/(?:^|[，,。；;])(?:本科|硕士|博士|大专|高中|初中)学历/.test(answer)||/(?:我|本人)[^，,。；;]{0,12}(?:本科|硕士|博士|大专|专科|高中|初中|小学|学历)/.test(answer))?education(answer):null;
  const explicitRole=answer.match(/(?:^|[，,。；;])(?:我)?(?:现在|目前)(?:主要)?(?:是|做|从事)([^，,。；;]+)/);if(explicitRole){const role=explicitRole[1].split(/(?:我)?(?:擅长|每周|今年|最高学历|主要困难)/)[0].trim();if(role)set('role',role,explicitRole[0]);}
  const explicitSkills=answer.match(/擅长([^，,。；;]+)/);if(explicitSkills&&!/(?:不|没|不太|不是很)擅长/.test(answer))set('skills',explicitSkills[1].trim(),explicitSkills[0]);
  const explicitObstacle=answer.match(/(?:主要困难(?:是)?|障碍(?:是)?|卡住我的是|现实限制(?:是)?)[：: ]?([^。；;]+)/);if(explicitObstacle)set('constraints',explicitObstacle[1].trim(),explicitObstacle[0]);
  if(a)set('age',a,answer);if(h!==null&&(field==='hours'||/每周|一周|每星期/.test(answer)))set('hours',h,answer);if(e)set('education',e,answer);
  for(const f of modelFacts||[]){
   if(!fields.includes(f.field)||!f.evidence||!answer.includes(f.evidence)||!known(f.value)||evidence[f.field])continue;
   if(f.field==='age'){if(/孩子|女儿|儿子|父亲|母亲|爸爸|妈妈|妻子|丈夫/.test(f.evidence))continue;const n=age(f.evidence);if(n&&String(n)===String(f.value).replace(/岁$/,''))set(f.field,n,f.evidence)}
   else if(f.field==='hours'){const n=hours(f.evidence,true);if(n!==null&&n===Number(f.value))set(f.field,n,f.evidence)}
   else if(f.field==='education'){const n=education(f.evidence);if(n)set(f.field,n,f.evidence)}
   else if(String(f.evidence).includes(String(f.value))||String(f.value).includes(String(f.evidence)))set(f.field,String(f.value).slice(0,2000),f.evidence);
  }
  return {profile:next,evidence};
 }
 function next(profile,asked=[],skipped=[],kind='initial'){
  const seen=new Set([...asked,...skipped]);
  if(kind==='checkin')return ['recentUpdate','experience','interests'].find(k=>!seen.has(k))||null;
  const order=[...required];
  if(/忙|时间|加班/.test(profile.constraints||'')&&!known(profile.hours)){order.splice(order.indexOf('hours'),1);order.splice(Math.max(1,order.indexOf('constraints')+1),0,'hours')}
  return order.find(k=>!known(profile[k])&&!seen.has(k))||null;
 }
 function question(field,p={}){
  return ({goal:'最近有什么事，是你特别想改变的？',role:/换工作|转行|职业/.test(p.goal||'')?'你现在主要做什么工作，或处在哪个阶段？':'你平时主要做些什么？',constraints:'你觉得，现在最难的是哪一块？',age:'方便问下，你今年多大了？',education:'你读到哪个学历？也可以先跳过。',skills:'你觉得自己最拿手的是什么？日常的小事也算。',hours:'一周里，大概能留几小时给这件事？',resources:'目前有什么人、工具或资源能帮上一点忙？',experience:'这段时间有没有一件让你印象深的经历？',interests:'最近你更愿意把时间花在哪件感兴趣的事情上？',recentUpdate:'这两周，生活或想法有什么新变化？'}[field]||'还有什么想让我了解的？');
 }
 const options={goal:['工作更自主','增加收入来源','把一项技能变成作品','生活更有节奏'],role:['在职工作','正在学习','暂时休息或寻找机会','经营自己的事情'],constraints:['时间不够','不知道怎么开始','预算有限','担心失败或被拒绝'],age:[],education:['高中 / 中专','大专','本科','硕士','博士','其他'],skills:['沟通与协调','写作与表达','数据与表格','设计与创作','暂时说不清'],hours:['0.5小时','2小时','4小时','8小时'],recentUpdate:['最近没有明显变化','时间安排变了','目标有了新想法'],experience:['有一件小进展','遇到了一次挫折','暂时没有想补充的'],interests:['学习新东西','创作或表达','运动与户外','与人交流']};
 function due(n,now=Date.now()){return !n.demo&&now-new Date(n.lastConversationAt||n.conversationStartedAt||new Date(now).toISOString()).getTime()>=14*86400000}
 return {fields,labels,required,isNoiseTranscript,known,clean,number,age,hours,education,apply,next,question,options,due};
})();


/** Account / OTP stubs — isomorphic (no node:fs / node:crypto). File persist is optional via env hooks. */

const phoneOk=p=>/^1\d{10}$/.test(String(p||'').trim());
const maskPhone=p=>{const s=String(p||'');return s.length===11?s.slice(0,3)+'****'+s.slice(7):'****'};
const authJson=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'}});

function bytesToHex(buf){return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function hashCode(code,pepper){
 const data=new TextEncoder().encode((pepper||'dev-otp-pepper')+':'+String(code));
 if(globalThis.crypto?.subtle){const dig=await crypto.subtle.digest('SHA-256',data);return bytesToHex(dig)}
 // Fallback for rare environments without subtle
 let h=2166136261>>>0;for(const c of data){h^=c;h=Math.imul(h,16777619)>>>0}return ('00000000'+h.toString(16)).slice(-8).padStart(64,'0');
}
function newToken(){
 const a=new Uint8Array(24);
 (globalThis.crypto||{getRandomValues:x=>{for(let i=0;i<x.length;i++)x[i]=Math.floor(Math.random()*256);return x}}).getRandomValues(a);
 return bytesToHex(a);
}
function now(){return Date.now()}
function safeEqual(a,b){
 if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;
 let d=0;for(let i=0;i<a.length;i++)d|=a.charCodeAt(i)^b.charCodeAt(i);return d===0;
}

function createAccountStore(options={}){
 const state=options.state||{users:{},otps:{},sessions:{}};
 const onChange=typeof options.onChange==='function'?options.onChange:null;
 const touch=()=>{try{onChange?.(state)}catch{/* ignore */}};
 const api={
  _state:state,
  reset(){state.users={};state.otps={};state.sessions={};touch()},
  getUser(phone){return state.users[phone]||null},
  getSession(token){
   const s=state.sessions[token];
   if(!s||s.expiresAt<now()){if(s)delete state.sessions[token];return null}
   const user=state.users[s.phone];
   if(!user||user.deletedAt)return null;
   return {token,phone:s.phone,user};
  },
  async sendCode({phone,agreedTerms,agreedPrivacy,env}){
   if(!phoneOk(phone))return {ok:false,status:400,error:'请输入有效的中国大陆手机号',code:'PHONE_INVALID'};
   if(!agreedTerms||!agreedPrivacy)return {ok:false,status:400,error:'请先勾选《用户协议》和《隐私政策》',code:'CONSENT_REQUIRED'};
   const provider=String(env?.SMS_PROVIDER||'mock').toLowerCase();
   if(provider!=='mock'){
    return {ok:false,status:503,error:'短信通道密钥未配置，开发期请设 SMS_PROVIDER=mock',code:'SMS_STUB_ONLY'};
   }
   const cooldown=Number(env?.AUTH_OTP_COOLDOWN_SEC)||60;
   const ttl=Number(env?.AUTH_OTP_TTL_SEC)||300;
   const prev=state.otps[phone];
   if(prev&&prev.sentAt+cooldown*1000>now()){
    return {ok:false,status:429,error:'验证码发送过于频繁，请稍后再试',code:'OTP_COOLDOWN',cooldownSec:Math.ceil((prev.sentAt+cooldown*1000-now())/1000)};
   }
   const code='000000';
   state.otps[phone]={hash:await hashCode(code,env?.AUTH_OTP_PEPPER),expiresAt:now()+ttl*1000,sentAt:now(),tries:0};
   touch();
   return {ok:true,status:200,data:{ok:true,cooldownSec:cooldown,mock:true,maskedPhone:maskPhone(phone)}};
  },
  async verifyCode({phone,code,env}){
   if(!phoneOk(phone))return {ok:false,status:400,error:'请输入有效的中国大陆手机号',code:'PHONE_INVALID'};
   const rec=state.otps[phone];
   if(!rec)return {ok:false,status:400,error:'请先获取验证码',code:'OTP_MISSING'};
   if(rec.expiresAt<now()){delete state.otps[phone];touch();return {ok:false,status:400,error:'验证码已过期，请重新获取',code:'OTP_EXPIRED'};}
   if(rec.tries>=5){delete state.otps[phone];touch();return {ok:false,status:400,error:'验证码错误次数过多，请重新获取',code:'OTP_LOCKED'};}
   const got=await hashCode(String(code||'').trim(),env?.AUTH_OTP_PEPPER);
   if(!safeEqual(rec.hash,got)){
    rec.tries+=1;touch();
    return {ok:false,status:400,error:'验证码不正确',code:'OTP_INVALID'};
   }
   delete state.otps[phone];
   let user=state.users[phone];
   if(!user||user.deletedAt){
    user={phone,createdAt:new Date().toISOString(),deletedAt:null,consents:{terms:true,privacy:true,sensitive:false,termsAt:new Date().toISOString(),privacyAt:new Date().toISOString()},journey:null};
    state.users[phone]=user;
   }else{
    user.consents={...user.consents,terms:true,privacy:true,termsAt:new Date().toISOString(),privacyAt:new Date().toISOString()};
   }
   const token=newToken();
   const lifetime=(Number(env?.AUTH_SESSION_TTL_SEC)||7*24*3600)*1000;
   state.sessions[token]={phone,expiresAt:now()+lifetime};
   touch();
   return {ok:true,status:200,data:{ok:true,token,phone:maskPhone(phone),sensitiveConsent:Boolean(user.consents?.sensitive),hasJourney:Boolean(user.journey)}};
  },
  setSensitiveConsent(phone,agreed){
   const user=state.users[phone];if(!user||user.deletedAt)return false;
   user.consents={...user.consents,sensitive:Boolean(agreed),sensitiveAt:agreed?new Date().toISOString():null};
   touch();return true;
  },
  saveJourney(phone,journey){
   const user=state.users[phone];if(!user||user.deletedAt)return false;
   user.journey=journey;user.updatedAt=new Date().toISOString();touch();return true;
  },
  exportUser(phone){
   const user=state.users[phone];if(!user||user.deletedAt)return null;
   return {exportedAt:new Date().toISOString(),phone:maskPhone(phone),consents:user.consents,createdAt:user.createdAt,updatedAt:user.updatedAt||null,journey:user.journey};
  },
  deleteUser(phone){
   const user=state.users[phone];if(!user)return false;
   user.deletedAt=new Date().toISOString();
   user.journey=null;
   user.consents={terms:false,privacy:false,sensitive:false};
   for(const [tok,s] of Object.entries(state.sessions))if(s.phone===phone)delete state.sessions[tok];
   touch();return true;
  }
 };
 return api;
}

let sharedStore=null;
function getAccountStore(env){
 if(env?.__accountStore)return env.__accountStore;
 if(!sharedStore){
  const persist=env?.__accountPersist;
  let state;try{state=persist?.load?.()||undefined}catch{state=undefined}
  sharedStore=createAccountStore(persist?{state,onChange:s=>persist.save(s)}:{});
 }
 return sharedStore;
}
function __resetAccountStoreForTests(){
 sharedStore=createAccountStore({});
 return sharedStore;
}

function bearerToken(request){
 // P0-25: normalize multi-value headers some proxies leave as arrays
 const one=v=>{if(Array.isArray(v))v=v.find(Boolean)||'';return String(v||'').trim();};
 const h=one(request.headers.get('authorization'));
 if(h.toLowerCase().startsWith('bearer '))return h.slice(7).trim();
 return one(request.headers.get('x-butterfly-session'));
}

async function handleAccountApi(request,env,store){
 const url=new URL(request.url);
 const path=url.pathname;
 const storeApi=store||getAccountStore(env);

 if(path==='/api/auth/send-code'){
  if(request.method!=='POST')return authJson({error:'不支持此操作'},405);
  if(request.headers.get('origin')!==url.origin)return authJson({error:'请求来源不匹配'},403);
  let body;try{body=JSON.parse(await request.text())}catch{return authJson({error:'输入格式无效'},400)}
  const result=await storeApi.sendCode({
   phone:String(body.phone||'').trim(),
   agreedTerms:Boolean(body.agreedTerms),
   agreedPrivacy:Boolean(body.agreedPrivacy),
   env
  });
  if(!result.ok)return authJson({error:result.error,code:result.code,cooldownSec:result.cooldownSec},result.status);
  return authJson(result.data);
 }

 if(path==='/api/auth/verify-code'){
  if(request.method!=='POST')return authJson({error:'不支持此操作'},405);
  if(request.headers.get('origin')!==url.origin)return authJson({error:'请求来源不匹配'},403);
  let body;try{body=JSON.parse(await request.text())}catch{return authJson({error:'输入格式无效'},400)}
  const result=await storeApi.verifyCode({phone:String(body.phone||'').trim(),code:String(body.code||'').trim(),env});
  if(!result.ok)return authJson({error:result.error,code:result.code},result.status);
  return authJson(result.data);
 }

 const token=bearerToken(request);
 const session=token?storeApi.getSession(token):null;

 if(path==='/api/auth/me'){
  if(request.method!=='GET')return authJson({error:'不支持此操作'},405);
  if(!session)return authJson({error:'请先登录',code:'AUTH_REQUIRED'},401);
  return authJson({ok:true,phone:maskPhone(session.phone),sensitiveConsent:Boolean(session.user.consents?.sensitive),hasJourney:Boolean(session.user.journey)});
 }

 if(path==='/api/auth/sensitive-consent'){
  if(request.method!=='POST')return authJson({error:'不支持此操作'},405);
  if(request.headers.get('origin')!==url.origin)return authJson({error:'请求来源不匹配'},403);
  if(!session)return authJson({error:'请先登录',code:'AUTH_REQUIRED'},401);
  let body;try{body=JSON.parse(await request.text())}catch{return authJson({error:'输入格式无效'},400)}
  if(!body.agreed)return authJson({error:'请勾选敏感信息处理同意',code:'SENSITIVE_REQUIRED'},400);
  storeApi.setSensitiveConsent(session.phone,true);
  return authJson({ok:true,sensitiveConsent:true});
 }

 if(path==='/api/account/export'){
  if(request.method!=='GET')return authJson({error:'不支持此操作'},405);
  if(!session)return authJson({error:'请先登录',code:'AUTH_REQUIRED'},401);
  const data=storeApi.exportUser(session.phone);
  if(!data)return authJson({error:'账号不存在或已注销',code:'ACCOUNT_GONE'},404);
  return authJson({ok:true,data});
 }

 if(path==='/api/account/delete'){
  if(request.method!=='POST')return authJson({error:'不支持此操作'},405);
  if(request.headers.get('origin')!==url.origin)return authJson({error:'请求来源不匹配'},403);
  if(!session)return authJson({error:'请先登录',code:'AUTH_REQUIRED'},401);
  let body={};try{const raw=await request.text();if(raw)body=JSON.parse(raw)}catch{return authJson({error:'输入格式无效'},400)}
  if(body.confirm!=='DELETE')return authJson({error:'请确认注销：confirm 须为 DELETE',code:'CONFIRM_REQUIRED'},400);
  storeApi.deleteUser(session.phone);
  return authJson({ok:true,deleted:true});
 }

 if(path==='/api/account/journey'){
  if(!session)return authJson({error:'请先登录',code:'AUTH_REQUIRED'},401);
  if(request.method==='GET'){
   return authJson({ok:true,journey:session.user.journey||null,sensitiveConsent:Boolean(session.user.consents?.sensitive)});
  }
  if(request.method==='PUT'){
   if(request.headers.get('origin')!==url.origin)return authJson({error:'请求来源不匹配'},403);
   let body;try{body=JSON.parse(await request.text())}catch{return authJson({error:'输入格式无效'},400)}
   const journey=body.journey??body;
   if(!journey||typeof journey!=='object')return authJson({error:'旅程数据无效'},400);
   storeApi.saveJourney(session.phone,journey);
   return authJson({ok:true});
  }
  return authJson({error:'不支持此操作'},405);
 }

 return null;
}


/** P0-29 深度契约：plan（规划你的下一步）与 projection story（推演叙事）共用口径。
 * S2：同构字段（处境·行动·变化·代价显式）+ 规则周界不越出 ruleFacts + 近端今天/本周。
 * 合规不松档：禁算命/保证成功；数字尽量来自规则层注入，模型少编造。
 */
const DEPTH_CONTRACT_VERSION='p0-29-s2-isomorphic-v1';

const QUAD_FIELDS=[['situation','处境'],['action','行动'],['change','变化'],['cost','代价']];

/** 从目标文案解析中期期限（天）；解析失败返回 null。 */
function parseGoalDeadlineDays(goal=''){
 const s=String(goal||'');
 let m=s.match(/(\d+)\s*天/);if(m)return Math.min(730,Math.max(7,Number(m[1])));
 m=s.match(/(\d+)\s*周/);if(m)return Math.min(730,Math.max(7,Number(m[1])*7));
 m=s.match(/(\d+)\s*个?月/);if(m)return Math.min(730,Math.max(7,Number(m[1])*30));
 m=s.match(/半年/);if(m)return 180;
 m=s.match(/一年|1年/);if(m)return 365;
 return null;
}

/** 规则层事实：期限、阶段骨架、可用时间——注入提示词，禁止模型另编周数/金额。 */
function buildRuleFacts(profile={}){
 const days=parseGoalDeadlineDays(profile.goal||profile.longGoal||'');
 const weeks=days!=null?Math.max(1,Math.round(days/7)):null;
 const hours=Number.isFinite(Number(profile.hours))?Number(profile.hours):null;
 const stages=weeks==null?null:[
  {key:'near',label:'近期（今天/本周/本阶段起步）',weekLo:0,weekHi:Math.min(2,weeks)},
  {key:'build',label:'能力与证据积累',weekLo:Math.min(2,weeks),weekHi:Math.min(Math.max(4,Math.round(weeks*0.45)),weeks)},
  {key:'mid',label:'中期目标验证前夜',weekLo:Math.min(Math.max(4,Math.round(weeks*0.45)),weeks),weekHi:weeks},
  {key:'verify',label:'阶段目标验证（不越界）',weekLo:Math.max(0,weeks-Math.min(4,Math.round(weeks*0.2))),weekHi:weeks}
 ];
 return {
  version:DEPTH_CONTRACT_VERSION,
  goalText:String(profile.goal||'').slice(0,200),
  deadlineDays:days,
  deadlineWeeks:weeks,
  hoursPerWeek:hours,
  stages,
  note:'下列周数/期限仅供叙事对齐；模型不得另编天数、周数、收入或成功概率。期限合计不得越界。'
 };
}

/** 从正文抽取固定标签分块；缺任一标签则返回 null。 */
function extractQuadFromText(text=''){
 const s=String(text||'');
 const found=QUAD_FIELDS.map(([k,zh])=>{
  const m=s.match(new RegExp('【\\s*'+zh+'\\s*】'));
  return m?{k,zh,at:m.index,len:m[0].length}:null;
 });
 if(found.some(x=>!x))return null;
 const sorted=[...found].sort((a,b)=>a.at-b.at);
 const out={};
 for(let i=0;i<sorted.length;i++){
  const start=sorted[i].at+sorted[i].len;
  const end=i+1<sorted.length?sorted[i+1].at:s.length;
  out[sorted[i].k]=s.slice(start,end).replace(/^\s+|\s+$/g,'');
 }
 return out;
}

/** 四元 → 固定标签叙事（plan / 推演同构可读）。 */
function assembleNarrativeFromQuad(q={}){
 return QUAD_FIELDS.map(([k,zh])=>'【'+zh+'】'+String(q[k]||'').trim()).join('\n');
}

/** 章节是否具备可逐项验收的显式四元（字段或标签分块）。 */
function chapterHasExplicitQuad(c={}){
 if(c&&['situation','action','change','cost'].every(k=>String(c[k]||'').trim().length>=8))return true;
 const q=extractQuadFromText(c?.narrative||'');
 return !!(q&&['situation','action','change','cost'].every(k=>String(q[k]||'').trim().length>=8));
}

/** 归一：抽出/回填四元字段，并保证 narrative 含固定标签（便于同构验收）。 */
function ensureChapterQuad(chapter={}){
 const c={...chapter};
 let q=null;
 if(['situation','action','change','cost'].every(k=>String(c[k]||'').trim())){
  q={situation:String(c.situation).trim(),action:String(c.action).trim(),change:String(c.change).trim(),cost:String(c.cost).trim()};
 }else{
  q=extractQuadFromText(c.narrative||'');
 }
 if(q){
  c.situation=q.situation;c.action=q.action;c.change=q.change;c.cost=q.cost;
  if(!extractQuadFromText(c.narrative||''))c.narrative=assembleNarrativeFromQuad(q);
 }
 return c;
}

/**
 * 推演叙事用同构脊柱：恰好 4 段，周界落在 ruleFacts.deadlineWeeks 内。
 * 不改动 computeProjection 算法（不开 B）；只在故事层对齐规划四幕。
 */
function depthStoryNodes(planNodes=[],ruleFacts=null){
 const nodes=Array.isArray(planNodes)?planNodes:[];
 const maxW=ruleFacts?.deadlineWeeks;
 const stages=Array.isArray(ruleFacts?.stages)?ruleFacts.stages:[];
 if(!maxW||!nodes.length)return nodes;
 const work=nodes.filter(n=>n&&n.dim!=='goal');
 const goal=nodes.find(n=>n&&n.dim==='goal')||work.at(-1)||nodes.at(-1);
 const picks=[
  work[0]||nodes[0],
  work[1]||work[0]||nodes[0],
  work[2]||work[1]||work[0]||nodes[0],
  goal
 ];
 const spineStages=stages.length>=4?stages.slice(0,4):[
  {key:'near',label:'近期起步',weekLo:0,weekHi:Math.min(2,maxW)},
  {key:'build',label:'能力积累',weekLo:Math.min(2,maxW),weekHi:Math.min(Math.max(4,Math.round(maxW*0.45)),maxW)},
  {key:'mid',label:'中期推进',weekLo:Math.min(Math.max(4,Math.round(maxW*0.45)),maxW),weekHi:maxW},
  {key:'verify',label:'阶段验证',weekLo:Math.max(0,maxW-Math.min(4,Math.round(maxW*0.2))),weekHi:maxW}
 ];
 return spineStages.map((st,i)=>{
  const src=picks[i]||picks[0];
  const lo=Math.max(1,Number(st.weekLo)||1);
  const hi=Math.max(lo+1,Math.min(maxW,Number(st.weekHi)||maxW));
  const title=(String(st.label||'').replace(/（[^）]*）/g,'').trim())||src.title||('阶段'+(i+1));
  return {
   ...src,
   id:'d_'+st.key,
   title,
   dim:src.dim||(i===3?'goal':['time','ability','experience','goal'][i]),
   tRange:{lo,hi},
   duration:{lo:Math.max(1,hi-lo),hi:Math.max(1,hi-lo)},
   depthStage:st.key,
   sourceNodeId:src.id,
   state:src.state||{gap:'按规则层阶段推进',role:'具备本阶段条件',life:'保持每周可投入节奏'},
   evidence:src.evidence||[]
  };
 });
}

/** 返回仅故事层使用的 proj 浅拷贝（plan line 换成同构脊柱）。 */
function withDepthStoryProj(proj,ruleFacts){
 if(!proj||!ruleFacts?.deadlineWeeks)return proj;
 const plan=(proj.lines||[]).find(l=>l.kind==='plan')||{nodes:[],horizon:null};
 const nodes=depthStoryNodes(plan.nodes||[],ruleFacts);
 if(!nodes.length)return proj;
 const horizon={lo:Math.min(...nodes.map(n=>n.tRange.lo)),hi:Math.max(...nodes.map(n=>n.tRange.hi))};
 const lines=(proj.lines||[]).map(l=>l.kind==='plan'?{...l,nodes,horizon,depthSpine:true,ruleHorizonWeeks:ruleFacts.deadlineWeeks}:l);
 return {...proj,lines,depthContract:true,ruleFacts};
}

/** 以 plan 第一章 quests（或显式 nearTerm）为权威，抽出与推演同构的 nearTerm 对（今天/本周）。 */
function nearTermFromPlanStory(planStory){
 if(!planStory||typeof planStory!=='object')return null;
 const nt=planStory.nearTerm;
 if(nt&&typeof nt==='object'){
  const today=nt.today&&typeof nt.today==='object'?nt.today:{title:nt.todayTitle,output:nt.todayOutput,minutes:nt.todayMinutes};
  const week=nt.week&&typeof nt.week==='object'?nt.week:{title:nt.weekTitle,output:nt.weekOutput,minutes:nt.weekMinutes};
  const tTitle=String(today?.title||'').trim(),wTitle=String(week?.title||'').trim();
  if(tTitle.startsWith('今天：')&&wTitle.startsWith('本周：')){
   return {
    today:{title:tTitle,output:String(today?.output||'').trim(),minutes:Number(today?.minutes)||20},
    week:{title:wTitle,output:String(week?.output||'').trim(),minutes:Number(week?.minutes)||30},
    source:'plan'
   };
  }
 }
 const q=planStory?.chapters?.[0]?.quests;
 if(!Array.isArray(q)||q.length<2)return null;
 const today=q[0],week=q[1];
 const tTitle=String(today?.title||'').trim(),wTitle=String(week?.title||'').trim();
 if(!tTitle.startsWith('今天：')||!wTitle.startsWith('本周：'))return null;
 return {
  today:{title:tTitle,output:String(today?.output||'').trim(),minutes:Number(today?.minutes)||20},
  week:{title:wTitle,output:String(week?.output||'').trim(),minutes:Number(week?.minutes)||30},
  source:'plan'
 };
}

/** plan / adjust 追加的深度契约（短篇感 + 显式四元 + 近端可执行）。 */
function planDepthContractText(ruleFacts,{enabled=true}={}){
 if(!enabled)return '';
 const rf=ruleFacts||{};
 const horizon=rf.deadlineDays!=null
  ?(`中期期限已由规则层锁定为约 ${rf.deadlineDays} 天（约 ${rf.deadlineWeeks} 周）；四幕 period 合计覆盖到该中期，不得擅自缩短为数周完成，也不得越界。`)
  :('目标未给出明确天数时，仍按中长期人生阶段写四幕，近端具体、远期有条件；不得编造精确周数。');
 const stageHint=Array.isArray(rf.stages)
  ?('建议阶段骨架（仅供对齐，可微调措辞不可改周界）：'+JSON.stringify(rf.stages)+'。')
  :'';
 return [
  ' 【P0-29 S2 深度契约·与推演叙事同构】',
  '1) 主路径须写成连贯短篇人生轨迹：每幕 narrative 汉字≥400，四幕合计≥1600（验收硬门槛≥1500，请留余量）；短篇感而非条目表。',
  '2) 每幕必须输出显式四元字段 situation/action/change/cost（各≥40汉字），且 narrative 用固定标签分块书写：【处境】…【行动】…【变化】…【代价】…（标签不可省略，便于逐项验收）。禁止只在散文里点到「变化/代价」而无标签/字段。',
  '3) '+horizon+stageHint,
  '4) 近端：第一章quests恰好2个（今天：/本周：），写明时限、交付物、验收标准；gate 只写本人可控证据，不要求他人回复/成交/录取。',
  '5) 具名或可查动作细节（工具名、表格列、话术模板用____占位）；阿拉伯数字的周数/天数/小时尽量只用规则层已给出的值，禁止编造收入、成功率、涨薪幅度。',
  '6) 合规：禁止算命、改命、保证成功、包过、稳赚、一定能、命运预测等表述；计划是有条件路线。',
  '7) 与导航推演故事同一深度：禁止只出薄草案提纲；读者应能在5分钟内复述本周第一步与过关标准。'
 ].join('');
}

/** projection-story 系统提示追加：与 plan 同深度口径 + 周界。 */
function projectionStoryDepthAddon(ruleFacts=null){
 const rf=ruleFacts||{};
 const bound=rf.deadlineWeeks!=null
  ?(`本条推演叙事周界锁定为约 ${rf.deadlineWeeks} 周（${rf.deadlineDays||''}天），不得写到更远的几十周。`)
  :('周界由规则层节点标注；正文仍不得出现数字。');
 return [
  '',
  '【P0-29 S2 深度口径·与规划同构】四要素写细、可信、可照做；行动写每周具体做法；代价写真实取舍；变化只写可观察状态。',
  '整条行动线连读应有短篇人生轨迹感（中长期阶段为主轴，近端可执行），不是条目摘要。',
  bound,
  '禁止算命/保证成功；周数与收入数字由系统标注，正文仍不得出现数字。'
 ].join('\n');
}

/** 环境开关：默认开启深度契约；设 AI_DEPTH_CONTRACT=0 可回退旧基线便于对照。 */
function depthContractEnabled(env={}){
 const v=String(env.AI_DEPTH_CONTRACT??'1').trim().toLowerCase();
 return !(v==='0'||v==='false'||v==='off'||v==='no');
}

