export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith("/api/"))return api(request,env);if(!["GET","HEAD"].includes(request.method))return new Response("Method not allowed",{status:405});const a=assets[url.pathname==="/"?"/index.html":url.pathname];if(!a)return new Response("Not found",{status:404});return new Response(request.method==="HEAD"?null:Uint8Array.from(atob(a.body),c=>c.charCodeAt(0)),{headers:{"Content-Type":a.type,"Cache-Control":"no-cache","X-Content-Type-Options":"nosniff"}})}};
